ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"osKey": now() as String {format: "YYYY-MM-dd"}
}

ee:message.ee:set-payload:
%dw 2.0
output application/java
fun stripMemberId(id: String) = if (id contains "-") (id splitBy "-")[1] else id
fun getNoticeState(fineCode: String, workflowState: String) = do {
    var t1First = ["1ST NOTIFIED CORRECTABLE", "CORRECTABLE NOTIFIED"]
    var t1Second = ["FINEABLE", "FINED", "CORRECTABLE FINEABLE", "CORRECTABLE FINED"]
    var t1Third = ["CORRECTABLE SUBSEQUENT FINEABLE", "CORRECTABLE SUBSEQUENT FINED"]
    var t1Fourth = ["TERMINATION NOTIFY", "TERMINATION NOTIFIED"]
    var t2First = ["IMMEDIATE FINEABLE", "IMMEDIATE FINED"]
    var t2Second = ["SUBSEQUENT FINEABLE", "SUBSEQUENT FINED"]
    //var correctedStates = ["CORRECTABLE CORRECTED", "CORRECTED", "SYSTEM CORRECTED"]
    var waivedStates = ["FINE WAIVED", "FINE WAIVED NO APPEAL"]
    ---
    //if (correctedStates contains upper(workflowState)) "Corrected"
    //else 
    if (waivedStates contains upper(workflowState)) "Waived"
    else if (["Type 1", "TYPE 1"] contains fineCode) (
        if (t1First contains workflowState) "First Violation"
        else if (t1Second contains workflowState) "Second Violation"
        else if (t1Third contains workflowState) "Third Violation"
        else if (t1Fourth contains workflowState) "Fourth Notice"
        else null
    )
    else if (["Type 2", "TYPE 2"] contains fineCode) (
        if (t2First contains workflowState) "First Violation"
        else if (t2Second contains workflowState) "Second Violation"
        else null
    )
    else null
}
fun toNotifDateTime(d: String) = do {
    var parts = d splitBy "."
    var paddedMillis = ((if (sizeOf(parts) > 1) parts[1] else "000") ++ "000")[0 to 2]
    ---
    (parts[0] ++ "." ++ paddedMillis) as LocalDateTime {format: "yyyy-MM-dd HH:mm:ss.SSS"}
}
var sortedRows = (vars.violationDet."ldc-service"."fine-export".*"row" orderBy ($."Notif_Sent" default "")) reduce ((item, acc = []) -> [item] ++ acc)
---
{
	"records": sortedRows map {
	    ("Violation_Type__c": if(["Type 1", "TYPE 1"] contains $.FineCode) "Type 1 RLS Data Violation" else if (["Type 2", "TYPE 2"] contains $.FineCode) "Type 2 FHA Violation" else "") if (!isEmpty($.FineCode)),
	    "MLS_No__c": $."mlsno",
	    "Violation_Number__c": $."Violation_no",
	    "Violation_Wording__c": $."VIOLATION_NAME",
	    ("SECOND_Listing_Violation_alert_fee__c": now()) if($.FineAmount ~= 250 and (["Type 1", "TYPE 1"] contains $.FineCode)),
	    ("FIRST_FHA_Violation_alert__c": now()) if($.FineAmount ~= 500 and (["Type 2", "TYPE 2"] contains $.FineCode)),
	    ("Agent__c": stripMemberId($."k_listAgent")) if (!isEmpty($."k_listAgent")),
	    ("Broker_A__c": stripMemberId($."k_listBroker")) if (!isEmpty($."k_listBroker")),
	    "Status_detail__c": $."Workflow_State",
	    ("Violation_Status__c": "Violation Fixed" ) if (upper($."Workflow_State") contains "CORRECTED"),	    
	    ("Listing_Violation_fixed__c": now()) if ((upper($."Workflow_State") contains "CORRECTED") and ($.FineAmount ~= 250) and (["Type 1", "TYPE 1"] contains $.FineCode)),
	    ("FIRST_FHA_Violation_fixed__c": now()) if ((upper($."Workflow_State") contains "CORRECTED") and ($.FineAmount ~= 500) and (["Type 2", "TYPE 2"] contains $.FineCode)),
	    ("Current_Notice_State__c": getNoticeState($.FineCode, $."Workflow_State")) if (!isEmpty(getNoticeState($.FineCode, $."Workflow_State") default "")),
	    ("Notif_Sent__c": toNotifDateTime($."Notif_Sent")) if (!isEmpty($."Notif_Sent" default ""))
	}
}

%dw 2.0
output application/java
---
payload map (item, index) -> (item - "Agent__c") ++ (
    if (!isEmpty(item."Agent__c" default "")) {
        "Agent__c": vars.agentDetails[item."Agent__c"].contactId,
        "Agent_s_Company__c": vars.agentDetails[item."Agent__c"].accountId,
        "Company_Code__c": vars.agentDetails[item."Agent__c"].companyCode
    } else {}
)

%dw 2.0
output application/java
---
payload map (item, index) -> (item - "Broker_A__c") ++ {
    ("Broker_A__c": vars.brokerDetails[item."Broker_A__c"]) if (!isEmpty(vars.brokerDetails[item."Broker_A__c"] default ""))
}

%dw 2.0
output application/java
---
payload map (item, index) -> item ++ {
    "RLS_Violation_Tracker__c": vars.violationHeader[item."Violation_Number__c"]
}

