ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"host": Mule::p("api.host"),
	"port": Mule::p("api.port"),
	"method": "GET",
	"basePath": Mule::p("api.dos.basepath"),
	"path": "/dos-recursion",
	"header": {
		"x-client-id": Mule::p("secure::api.clientId"),
		"x-client-secret": Mule::p("secure::api.clientSecret"),
		"x-correlation-id": uuid()
	},
	"queryParam": {
		"offset": 0
	},
	"uriParam": {},
	"body": {}
}

%dw 2.0
output application/java
var hourGap=attributes.queryParams.lastModifiedGap default null
var tempDate=if(!isEmpty(hourGap)) ((now() >> "America/New_York") - "PT$(hourGap)M") else ""
var setQuery=if(isEmpty(tempDate)) (
	 "SELECT " ++ (vars.queryFields.fieldNames default "") ++ " FROM Contact" ++ (
  if (!isEmpty(vars.queryFields.whereClause)) 
    (" WHERE (" ++ vars.queryFields.whereClause ++")")
  else
    ""   
    )   )
  else (
  	"SELECT " ++ (vars.queryFields.fieldNames default "") ++ " FROM Contact" ++ (
  if (!isEmpty(vars.queryFields.whereClause)) 
    (" WHERE (" ++ vars.queryFields.whereClause ++ " AND SystemModStamp >= "++ tempDate ++")")
  else
    " WHERE (SystemModStamp >=" ++ tempDate ++")"   
    ) 
  )
---
{
	"username": Mule::p("secure::salesforce.new.username"), //Mule::p("secure::salesforce.int.username") for non-prod
	"password": Mule::p("secure::salesforce.new.password"),
	"token": Mule::p("secure::salesforce.new.token"),
	"authUrl": Mule::p("salesforce.authUrl"),
	"query": setQuery
}

